	@Test
	void retainedConditionScopeNameMappingPreservesModesAndCollapsesCollisions() {
		ConditionBindingScope retained = ConditionBindingScope.retain(Set.of("x", "y"));

		assertThat(ConditionBindingScope.AUTO.mapBindingNames(name -> "renamed")).isSameAs(ConditionBindingScope.AUTO);
		assertThat(ConditionBindingScope.ALL.mapBindingNames(name -> "renamed")).isSameAs(ConditionBindingScope.ALL);
		ConditionBindingScope empty = ConditionBindingScope.retain(Set.of());
		assertThat(empty.mapBindingNames(name -> "renamed")).isSameAs(empty);
		assertThat(retained.mapBindingNames(name -> name)).isSameAs(retained);
		assertThat(retained.mapBindingNames(name -> name.equals("x") ? "y" : name))
				.isEqualTo(ConditionBindingScope.retain(Set.of("y")));
	}

	@Test
	void existsProjectionSubqueryRetainsGuaranteedCorrelatedBindings() {
		StatementPattern outerPattern = pattern("s", "p", "x");
		Filter correlatedFilter = filter(pattern("z", "q", "v"), "x");
		Projection subquery = projection(correlatedFilter, "z");
		Filter root = new Filter(outerPattern, new Exists(subquery));

		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withGuaranteedInputNames(root, Set.of());
		QueryAlgebraBindingAnalysis.ReadOnlyContext filterInput = analysis.contextAt(correlatedFilter);

		assertThat(analysis.bindingState(Var.of("x"), filterInput))
				.as("EXISTS forwards the current row through its projected subquery")
				.isEqualTo(QueryAlgebraBindingAnalysis.BindingState.BOUND);
		assertThat(filterInput.guaranteedNames()).contains("x");
		assertThat(filterInput.externalValues()).doesNotContainKey("x");
		assertThat(filterInput.externalGuaranteedNames()).doesNotContain("x");
	}

