	@Test
	void lateralProjectionFactsUseEachCallerFrameAndKeepHiddenInputsScoped() {
		Value lateralValue = SimpleValueFactory.getInstance().createIRI("urn:lateral-value");
		Value apiValue = SimpleValueFactory.getInstance().createIRI("urn:api-current");
		Value rowValue = SimpleValueFactory.getInstance().createIRI("urn:row-current");
		Filter correlatedFilter = new Filter(new SingletonSet(), new Bound(Var.of("hidden")));
		Projection lateralSubquery = projection(correlatedFilter, "hidden", "projected");
		Lateral lateral = new Lateral(values("hidden", lateralValue), lateralSubquery, Set.of("hidden"));
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withGuaranteedInputNames(lateral,
				Set.of());

		assertThat(analysis.contextAt(correlatedFilter).fixedValues()).containsEntry("hidden", lateralValue);

		QueryAlgebraBindingAnalysis apiInputAnalysis = QueryAlgebraBindingAnalysis.withBindingValues(new SingletonSet(),
				bindings("hidden", apiValue));
		assertLateralInputFacts(analysis, lateral, lateralSubquery, correlatedFilter,
				apiInputAnalysis.rootContext(), apiValue);
		assertThat(apiInputAnalysis.rootContext().externalValues()).containsEntry("hidden", apiValue);

		BindingSetAssignment rowValues = values("hidden", rowValue);
		QueryAlgebraBindingAnalysis rowInputAnalysis = QueryAlgebraBindingAnalysis.withGuaranteedInputNames(rowValues,
				Set.of());
		QueryAlgebraBindingAnalysis.ReadOnlyContext rowInput = rowInputAnalysis.rootContext()
				.withOutput(rowInputAnalysis.outputFacts(rowValues, rowInputAnalysis.rootContext()));
		assertThat(rowInput.externalValues()).doesNotContainKey("hidden");
		assertLateralInputFacts(analysis, lateral, lateralSubquery, correlatedFilter, rowInput, rowValue);

		LeftJoin nullableRows = new LeftJoin(new SingletonSet(), values("hidden", rowValue));
		QueryAlgebraBindingAnalysis nullableAnalysis = QueryAlgebraBindingAnalysis.withGuaranteedInputNames(
				nullableRows,
				Set.of());
		QueryAlgebraBindingAnalysis.ReadOnlyContext nullableInput = nullableAnalysis.rootContext()
				.withOutput(nullableAnalysis.outputFacts(nullableRows, nullableAnalysis.rootContext()));
		QueryAlgebraBindingAnalysis.OutputFacts nullableProjection = analysis.outputFacts(lateralSubquery,
				nullableInput);
		QueryAlgebraBindingAnalysis.ReadOnlyContext nullableOutput = nullableInput.withOutput(nullableProjection);
		assertThat(nullableAnalysis.bindingState(Var.of("hidden"), nullableInput))
				.isEqualTo(QueryAlgebraBindingAnalysis.BindingState.POSSIBLY_BOUND);
		assertThat(analysis.bindingState(Var.of("projected"), nullableOutput))
				.as("a projection cannot turn a nullable caller input into a known-unbound alias")
				.isEqualTo(QueryAlgebraBindingAnalysis.BindingState.POSSIBLY_BOUND);

		QueryAlgebraBindingAnalysis.ReadOnlyContext unknownInput = QueryAlgebraBindingAnalysis
				.withGuaranteedInputNames(new SingletonSet(), Set.of())
				.rootContext()
				.withUnknownDomain();
		QueryAlgebraBindingAnalysis.OutputFacts unknownProjection = analysis.outputFacts(lateralSubquery, unknownInput);
		QueryAlgebraBindingAnalysis.ReadOnlyContext unknownOutput = unknownInput.withOutput(unknownProjection);
		assertThat(unknownOutput.bindingDomainKnown()).isFalse();
		assertThat(analysis.bindingState(Var.of("projected"), unknownOutput))
				.as("a hidden projection cannot turn an unknown caller domain into known-unbound")
				.isEqualTo(QueryAlgebraBindingAnalysis.BindingState.UNKNOWN);
	}

	private void assertOrdinarySubqueryInput(String algorithm) {
		MapBindingSet input = bindings("entry", SimpleValueFactory.getInstance().createIRI("urn:entry"));
		Filter correlatedFilter = filter(pattern("z", "q", "v"), "x");
		Projection subquery = projection(correlatedFilter, "z");
		Join root = new Join(pattern("s", "p", "x"), subquery);
		root.setAlgorithm(algorithm);

		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(root, input);
		QueryAlgebraBindingAnalysis.ReadOnlyContext filterInput = analysis.contextAt(correlatedFilter);

		assertThat(analysis.bindingState(Var.of("entry"), filterInput))
				.as("%s preserves the incoming evaluator frame across a subquery boundary", algorithm)
				.isEqualTo(QueryAlgebraBindingAnalysis.BindingState.BOUND);
		assertThat(analysis.bindingState(Var.of("x"), filterInput))
				.as("%s does not inject its left row into a subquery", algorithm)
				.isEqualTo(QueryAlgebraBindingAnalysis.BindingState.UNBOUND);
	}

	private static void assertLateralInputFacts(QueryAlgebraBindingAnalysis analysis, Lateral lateral,
			Projection subquery, Filter filter, QueryAlgebraBindingAnalysis.ReadOnlyContext input, Value expected) {
		QueryAlgebraBindingAnalysis.ReadOnlyContext rightInput = analysis.childInput(lateral, subquery, input);
		QueryAlgebraBindingAnalysis.ReadOnlyContext filterInput = analysis.childInput(subquery, filter, rightInput);
		assertThat(analysis.bindingState(Var.of("hidden"), filterInput))
				.as("the subquery receives its current caller's hidden LATERAL input")
				.isEqualTo(QueryAlgebraBindingAnalysis.BindingState.BOUND);
		assertThat(filterInput.fixedValues()).containsEntry("hidden", expected);
		assertThat(analysis.outputFacts(subquery, rightInput).fixedValues()).containsEntry("projected", expected);
	}

	@Test
	void invalidationRefreshesJoinChildInputsAfterValuesRowsChange() {
		Value first = SimpleValueFactory.getInstance().createLiteral(1);
		Value replacement = SimpleValueFactory.getInstance().createLiteral(2);
		BindingSetAssignment values = values("x", first);
		Filter right = new Filter(new SingletonSet(), new Bound(Var.of("x")));
		Join root = new Join(values, right);
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withGuaranteedInputNames(root, Set.of());

		assertThat(analysis.contextAt(right).fixedValues()).containsEntry("x", first);

		values.setBindingSets(List.of(bindings("x", replacement)));
		analysis.invalidate();

		assertThat(analysis.contextAt(right).fixedValues())
				.as("child input facts must be recomputed after VALUES data changes")
				.containsEntry("x", replacement);
	}

	@Test
	void invalidationRefreshesLeftJoinInputAfterLeftChildChanges() {
		Value external = SimpleValueFactory.getInstance().createLiteral(1);
		LeftJoin root = new LeftJoin(new SingletonSet(), new Filter(new SingletonSet(), new Bound(Var.of("x"))));
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(root,
				bindings("x", external));
		TupleExpr originalLeft = root.getLeftArg();

		assertThat(analysis.contextAt(originalLeft).visibleNames()).doesNotContain("x");

		BindingSetAssignment replacementLeft = values("x", external);
		root.setLeftArg(replacementLeft);
		analysis.invalidate();

		assertThat(analysis.bindingState(Var.of("x"), analysis.contextAt(replacementLeft)))
				.as("the new OPTIONAL left operand declares x, so its evaluator input must retain x")
				.isEqualTo(QueryAlgebraBindingAnalysis.BindingState.BOUND);
	}

	private static Filter filter(TupleExpr argument, String name) {
		return new Filter(argument, new Compare(Var.of(name), new ValueConstant(
				SimpleValueFactory.getInstance().createLiteral(1))));
	}

	private static BindingSetAssignment values(String name, Value value) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingSets(List.of(bindings(name, value)));
		return assignment;
	}

	private static MapBindingSet bindings(String name, Value value) {
		MapBindingSet bindings = new MapBindingSet();
		bindings.addBinding(name, value);
		return bindings;
	}

	private static Projection projection(TupleExpr argument, String projectedName) {
		return new Projection(argument, new ProjectionElemList(new ProjectionElem(projectedName)), true);
	}

	private static Projection projection(TupleExpr argument, String sourceName, String projectedName) {
		return new Projection(argument, new ProjectionElemList(new ProjectionElem(sourceName, projectedName)), true);
	}

	private static StatementPattern pattern(String subject, String predicate, String object) {
		return new StatementPattern(Var.of(subject), Var.of(predicate), Var.of(object));
	}
